import{_ as a,o as s,c as e,ag as r}from"./chunks/framework.C5oN-8Wt.js";const o="/cns_master_docs/teaching-v0.2.0-alpha/03-sampling.svg",m=JSON.parse('{"title":"03 点少了，正弦就变成三角波了吗？","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/learn/03-sampling/index.md","filePath":"v0.2.0-alpha/learn/03-sampling/index.md"}'),n={name:"v0.2.0-alpha/learn/03-sampling/index.md"};function d(l,t,i,p,h,c){return s(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="_03-点少了-正弦就变成三角波了吗" tabindex="-1">03 点少了，正弦就变成三角波了吗？ <a class="header-anchor" href="#_03-点少了-正弦就变成三角波了吗" aria-label="Permalink to &quot;03 点少了，正弦就变成三角波了吗？&quot;">​</a></h1><p>适用 <strong>v0.2.0-alpha</strong>。前置：<a href="./../02-wave-quantities/">频率与周期</a>，以及除法。</p><h2 id="低空应用问题与学习目标" tabindex="-1">低空应用问题与学习目标 <a class="header-anchor" href="#低空应用问题与学习目标" aria-label="Permalink to &quot;低空应用问题与学习目标&quot;">​</a></h2><p>通信设备和计算机不能只存一句“连续变化”，需要按时间取值。本课用一个正弦源观察采样点，区分<strong>信号每秒变化几圈</strong>与<strong>每秒取几个数</strong>，并解释为什么稀疏采样的折线会显得有棱角。</p><p>把每隔相同时间记录一个数叫作均匀采样。采样率 Fs 的单位是 sample/s，采样间隔为 <code>1/Fs</code> 秒。一个周期里平均有 <code>Fs/f</code> 个样本。本组都是标量，一个 GNU item 就是一个样本；后续向量模块的一个 item 可能含多个分量，应另读其说明。</p><h2 id="工程与参数理由" tabindex="-1">工程与参数理由 <a class="header-anchor" href="#工程与参数理由" aria-label="Permalink to &quot;工程与参数理由&quot;">​</a></h2><p><a href="../../../downloads/teaching-v0.2.0-alpha/03-sampling.cnsproj" download>下载 03-sampling.cnsproj</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>信号源 1 out ──→ 观察器：时域（先数点）</span></span>
<span class="line"><span>             └─→ 观察器：频谱（再核对频率）</span></span></code></pre></div><p>初始设置：正弦、幅度 <strong>1</strong>、频率 <strong>64 Hz</strong>、相位 <strong>0 rad</strong>、偏置 <strong>0</strong>、采样率 <strong>1024 sample/s</strong>。这样每周期有 <code>1024/64 = 16</code> 点，先建立足够清楚的参照。工程已分别绑定时域与频谱观察器，可按下方步骤核对。频谱保持工程的 <strong>N=1024、周期 Hann、0% 重叠</strong>；N 是每帧使用的样本数，不是采样率。</p><h2 id="逐步操作" tabindex="-1">逐步操作 <a class="header-anchor" href="#逐步操作" aria-label="Permalink to &quot;逐步操作&quot;">​</a></h2><ol><li>打开工程，核对源参数。先设每路 <strong>4096</strong> 样本并 F5，完成后在时域观察器用滚轮或时基 <strong>+</strong> 缩到约四周期，即 <strong>0.0625 s</strong>。参数页可勾选“曲线样本标记”；显示方式和点数会影响是否逐点画圆点，部分实时曲线只标当前端点。不要用屏幕上的圆点总数推断采样率，可对照下方样本表和参考图数每周期的取样位置。</li><li>若自己创建观察器，在参数页确认信号源 <code>out</code>。频谱使用另一观察器，确认同节点的“频谱”输出，来源路径末尾为 <code>/out/spectrum</code>；不要给时域轴手动改个 Hz 标签冒充频谱。</li><li>记录采样间隔约 <strong>0.9765625 ms</strong>，一周期 16 点。先预测下方单参练习的结果。</li><li>停止，只将源的采样率改为 <strong>256 sample/s</strong>，其余不变，再 F5。保持相同的时间范围读图；不要直接比较自动铺满窗口后的线条密度。</li><li>看频谱主峰是否仍在 <strong>64 Hz</strong>。Fs 变小后每帧的 Hz 间隔也变小，读取新的坐标；不要拿前一轮的频点编号当作 Hz。</li></ol><h2 id="单参数对照-16-点与-4-点" tabindex="-1">单参数对照：16 点与 4 点 <a class="header-anchor" href="#单参数对照-16-点与-4-点" aria-label="Permalink to &quot;单参数对照：16 点与 4 点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>采样率</th><th>采样间隔</th><th>每周期点数</th><th>相位 0 的开头样本</th></tr></thead><tbody><tr><td>1024 sample/s</td><td>0.9765625 ms</td><td>16</td><td>0、约 0.3827、约 0.7071、约 0.9239……</td></tr><tr><td>256 sample/s</td><td>3.90625 ms</td><td>4</td><td>0、约 +1、约 0、约 −1，然后重复</td></tr></tbody></table><p>第二行把这些点用直线连接后，外观很像三角波。<strong>它表示四个离散正弦样本之间的连线，没有新增中间的实际采样值。</strong> 信号源仍配置为正弦；不能因为画线有棱角，就宣布源变成了三角波。</p><p><a href="/cns_master_docs/teaching-v0.2.0-alpha/03-sampling.svg"><img src="`+o+'" alt="实际 GNU 样本：采样率从 1024 改为 256，每周期由 16 点变为 4 点"></a></p><p>这张静态参考图明确标出实际取样位置，线段只是连接相邻样本。右图把两种采样率放在同一时间范围比较；相同的周期不代表取样点同样密。</p><p>同样的比例会出现在 <strong>Fs=4096 sample/s、f=1024 Hz</strong>：<code>4096/1024=4</code>，相位 0 的理想样本仍按 0、+1、0、−1 重复，周期为 <strong>0.9765625 ms</strong>。这组需要同时改采样率与信号频率，只用于理解等比例情形，不算上面的单参数对照。</p><h2 id="频谱为什么仍能有-64-hz-峰" tabindex="-1">频谱为什么仍能有 64 Hz 峰 <a class="header-anchor" href="#频谱为什么仍能有-64-hz-峰" aria-label="Permalink to &quot;频谱为什么仍能有 64 Hz 峰&quot;">​</a></h2><p>频谱分析用样本中的重复规律估计频率，不把画面上每一段直线当成真实连续信号。本例 64 Hz 小于 Fs/2，且满足本例理想单音条件，所以四点一周期仍可出现正确的主峰；时域图“圆不圆”与频率是否正确不是同一个问题。</p><p>对于没有混叠、频带受限的理想低通信号，采样率须<strong>严格大于最高信号频率的两倍</strong>，实际采集还要留过渡带并在采样前限制带宽。这个条件不等于“两点足够看清波形”，也不能只检查当前最明显的主峰而忽略噪声及其他频率。本课不连接真实模数转换器，不能验证硬件抗混叠能力。</p><p>采样后不同的连续信号可能得到同样的样本，这叫混叠。发布版源参数校验限制频率范围，不要用输入非法频率的方式强行完成混叠演示。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>先检查</th></tr></thead><tbody><tr><td>点很密，看不到标记</td><td>缩小时间范围，别只把窗口拉大。</td></tr><tr><td>采样率变小后同样样本数跑更久</td><td>实验时长是样本数除以 Fs；4096 点在 256 sample/s 下代表 16 s 的样本时间。</td></tr><tr><td>频谱没有出现</td><td>一帧要满 N 个样本；少于 1024 点不能生成本配置的完整帧。</td></tr><tr><td>相位不同，开头不再是 0、1、0、−1</td><td>对照表明确以相位 0 为前提，恢复相位后重跑。</td></tr><tr><td>想通过拖慢显示补出更多点</td><td>显示速度不增加采样信息；本课应调整真实 Fs，不能伪造中间点。</td></tr></tbody></table><p><a href="./../../modules/signal_source/">信号源</a> · <a href="./../">返回学习路径</a> · <a href="./../04-signal-views/">下一课：时域、频谱与瀑布 →</a></p>',24)])])}const u=a(n,[["render",d]]);export{m as __pageData,u as default};
